import { styled } from '@hexa-ui/theme';

export const StyledPerformanceToolContent = styled('div', {
  display: 'flex',
  flexDirection: 'column',
  gap: '24px',

  variants: {
    centered: {
      true: {
        width: '100%',
        justifyContent: 'center',
        alignItems: 'center',
      },
    },
  },
});
